 const mode=env.MAYOR_AUDIT_INFERENCE_MODE??'batch',model=env.MAYOR_AUDIT_MODEL??AUDIT_ANALYSIS_MODEL;
 if(!['batch','synchronous','streaming'].includes(mode)||!allowedModel(model)||mode==='batch'&&model===AUDIT_DEEPSEEK_MODEL)return null;
